(function () {
 var documentBase64='';
 var evidenceBase64='';
 var supplyBase64='';
 function decodeBase64(value){var bytes=Uint8Array.from(atob(value),function(c){return c.charCodeAt(0);});return new TextDecoder().decode(bytes);}
 window.mountOpportunityRadar=function(frame){
  var html=decodeBase64(documentBase64);
  var payload='<script>window.__EYE_CARE_EVIDENCE=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob("'+evidenceBase64+'"),function(c){return c.charCodeAt(0)})));window.__EYE_CARE_MARKET_SUPPLY=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob("'+supplyBase64+'"),function(c){return c.charCodeAt(0)})));</script>';
  frame.srcdoc=html.replace('</head>',payload+'</head>');
 };
})();
